  for select to authenticated
  using (auth_user_id = auth.uid());

create policy active_staff_can_read_products on public.products
  for select to authenticated
  using (
    exists (
      select 1 from public.staff_profiles sp
      where sp.auth_user_id = auth.uid() and sp.active
    )
  );

