-- BEGIN 002_auth_helpers.sql
create or replace function private.permissions_for_role(p_role public.staff_role)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select case p_role
    when 'cashier' then array['pos.read','pos.checkout','coupons.redeem']::text[]
    when 'inventory_admin' then array[
      'inventory.read','inventory.receive','inventory.adjust','inventory.product.manage','inventory.price.manage',
      'coupons.manage','reports.inventory','security.credentials.request'
    ]::text[]
    when 'accountant' then array[
      'wallet.read','wallet.adjust','reports.sales','reports.inventory','reports.wallets','reports.coupons',
      'security.credentials.request'
    ]::text[]
    when 'super_admin' then array[
      'pos.read','pos.checkout','coupons.redeem',
      'inventory.read','inventory.receive','inventory.adjust','inventory.product.manage','inventory.price.manage',
      'coupons.manage','wallet.read','wallet.adjust',
      'reports.sales','reports.inventory','reports.wallets','reports.coupons',
      'security.credentials.request','security.step_up','security.credentials.reset','security.staff.manage'
    ]::text[]
  end;
$$;

create or replace function private.role_has_permission(p_role public.staff_role, p_permission text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_permission = any(private.permissions_for_role(p_role));
$$;

create or replace function private.session_timeout(p_role public.staff_role)
returns interval
language sql
immutable
set search_path = ''
as $$
  select case when p_role = 'cashier' then interval '20 seconds' else interval '2 minutes' end;
$$;

create or replace function private.assert_session(p_session_id uuid, p_permission text)
returns private.staff_sessions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_profile public.staff_profiles;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;

  select * into v_session
  from private.staff_sessions
  where id = p_session_id
  for update;

  if not found
     or v_session.auth_user_id <> auth.uid()
     or v_session.revoked_at is not null
     or v_session.expires_at <= now() then
    raise exception 'SESSION_EXPIRED';
  end if;

  select * into v_profile
  from public.staff_profiles
  where auth_user_id = auth.uid();

  if not found or not v_profile.active or v_profile.role <> v_session.role_snapshot then
    raise exception 'FORBIDDEN';
  end if;

  if p_permission is not null and not private.role_has_permission(v_profile.role, p_permission) then
    raise exception 'FORBIDDEN';
  end if;

  update private.staff_sessions
  set last_activity_at = now(), expires_at = now() + private.session_timeout(v_profile.role)
  where id = v_session.id
  returning * into v_session;

  update private.terminals set last_seen_at = now() where id = v_session.terminal_id;
  return v_session;
end;
$$;

create or replace function private.assert_session_any(p_session_id uuid, p_permissions text[])
returns private.staff_sessions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_role public.staff_role;
  v_permission text;
begin
  select role_snapshot into v_role from private.staff_sessions where id = p_session_id;
  if not found then raise exception 'SESSION_EXPIRED'; end if;
  foreach v_permission in array p_permissions loop
    if private.role_has_permission(v_role, v_permission) then
      return private.assert_session(p_session_id, v_permission);
    end if;
  end loop;
  raise exception 'FORBIDDEN';
end;
$$;

create or replace function api.create_staff_session(
  p_employee_code text,
  p_session_token_hash text,
  p_terminal_fingerprint text
)
returns table(
  session_id uuid,
  user_id uuid,
  employee_code text,
  display_name text,
  role public.staff_role,
  permissions text[],
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_profile public.staff_profiles;
  v_terminal private.terminals;
  v_session private.staff_sessions;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;
  if length(p_session_token_hash) <> 64 or length(p_terminal_fingerprint) <> 64 then raise exception 'BAD_REQUEST'; end if;

  select * into v_profile from public.staff_profiles
  where auth_user_id = auth.uid() and lower(employee_code) = lower(p_employee_code) and active;
  if not found then raise exception 'FORBIDDEN'; end if;

  insert into private.terminals(terminal_fingerprint)
  values (p_terminal_fingerprint)
  on conflict (terminal_fingerprint) do update set last_seen_at = now()
  returning * into v_terminal;
  if not v_terminal.active then raise exception 'FORBIDDEN'; end if;

  update private.staff_sessions set revoked_at = now()
  where terminal_id = v_terminal.id and revoked_at is null;

  insert into private.staff_sessions(
    auth_user_id, employee_code_snapshot, role_snapshot, terminal_id,
    session_token_hash, expires_at
  ) values (
    auth.uid(), v_profile.employee_code, v_profile.role, v_terminal.id,
    p_session_token_hash, now() + private.session_timeout(v_profile.role)
  ) returning * into v_session;

  return query select
    v_session.id, v_profile.auth_user_id, v_profile.employee_code, v_profile.display_name,
    v_profile.role, private.permissions_for_role(v_profile.role), v_session.expires_at;
end;
$$;

create or replace function api.authorize_session(
  p_session_token_hash text,
  p_terminal_fingerprint text,
  p_permission text default null
)
returns table(
  session_id uuid,
  user_id uuid,
  employee_code text,
  display_name text,
  role public.staff_role,
  permissions text[],
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_profile public.staff_profiles;
  v_terminal private.terminals;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;

  select ss.* into v_session
  from private.staff_sessions ss
  join private.terminals t on t.id = ss.terminal_id
  where ss.session_token_hash = p_session_token_hash
    and t.terminal_fingerprint = p_terminal_fingerprint
    and t.active
  for update of ss;

  if not found
     or v_session.auth_user_id <> auth.uid()
     or v_session.revoked_at is not null
     or v_session.expires_at <= now() then
    raise exception 'SESSION_EXPIRED';
  end if;

  select * into v_profile from public.staff_profiles
  where auth_user_id = auth.uid() and active;
  if not found or v_profile.role <> v_session.role_snapshot then raise exception 'FORBIDDEN'; end if;
  if p_permission is not null and not private.role_has_permission(v_profile.role, p_permission) then raise exception 'FORBIDDEN'; end if;

  update private.staff_sessions
  set last_activity_at = now(), expires_at = now() + private.session_timeout(v_profile.role)
  where id = v_session.id
  returning * into v_session;

  update private.terminals set last_seen_at = now() where id = v_session.terminal_id;

  return query select
    v_session.id, v_profile.auth_user_id, v_profile.employee_code, v_profile.display_name,
    v_profile.role, private.permissions_for_role(v_profile.role), v_session.expires_at;
end;
$$;

create or replace function api.revoke_staff_session(p_session_token_hash text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update private.staff_sessions
  set revoked_at = now()
  where session_token_hash = p_session_token_hash and auth_user_id = auth.uid() and revoked_at is null;
end;
$$;
-- END 002_auth_helpers.sql

-- BEGIN 003_pos_functions.sql
create or replace function api.catalog(p_session_id uuid)
returns table(
  id uuid,
  sku text,
  name text,
  category text,
  selling_price_won bigint,
  stock_on_hand bigint,
  sold_out boolean
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session_any(p_session_id, array['pos.read','inventory.read']);
  return query
  select
    p.id, p.sku, p.name, p.category, p.selling_price_won,
    coalesce(sum(l.quantity_remaining), 0)::bigint as stock_on_hand,
    coalesce(sum(l.quantity_remaining), 0) <= 0 as sold_out
  from public.products p
  left join private.inventory_lots l on l.product_id = p.id and l.quantity_remaining > 0
  where p.active
  group by p.id, p.sku, p.name, p.category, p.selling_price_won
  order by p.category, p.name;
end;
$$;

create or replace function api.create_payment_intent(
  p_session_id uuid,
  p_items jsonb,
  p_idempotency_key uuid
)
returns table(
  intent_id uuid,
  state private.intent_state,
  total_won bigint,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_existing private.payment_intents;
  v_intent private.payment_intents;
  v_item record;
  v_product public.products;
  v_total bigint := 0;
  v_stock bigint;
begin
  v_session := private.assert_session(p_session_id, 'pos.checkout');
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 50 then
    raise exception 'BAD_REQUEST';
  end if;

  select * into v_existing from private.payment_intents where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.staff_session_id <> v_session.id then raise exception 'CONFLICT'; end if;
    return query select v_existing.id, v_existing.state, v_existing.total_won, v_existing.expires_at;
    return;
  end if;

  for v_item in
    select
      (entry->>'productId')::uuid as product_id,
      sum((entry->>'quantity')::integer)::integer as quantity
    from jsonb_array_elements(p_items) entry
    group by (entry->>'productId')::uuid
  loop
    if v_item.quantity < 1 or v_item.quantity > 99 then raise exception 'BAD_REQUEST'; end if;
    select * into v_product from public.products where id = v_item.product_id and active;
    if not found then raise exception 'NOT_FOUND'; end if;
    select coalesce(sum(quantity_remaining),0) into v_stock
      from private.inventory_lots where product_id = v_product.id and quantity_remaining > 0;
    if v_stock < v_item.quantity then raise exception 'INVENTORY_SHORTAGE'; end if;
    v_total := v_total + v_product.selling_price_won * v_item.quantity;
  end loop;
  if v_total <= 0 then raise exception 'BAD_REQUEST'; end if;

  insert into private.payment_intents(
    idempotency_key, staff_session_id, total_won, state, expires_at
  ) values (
    p_idempotency_key, v_session.id, v_total, 'awaiting_card', now() + interval '30 seconds'
  ) returning * into v_intent;

  for v_item in
    select
      (entry->>'productId')::uuid as product_id,
      sum((entry->>'quantity')::integer)::integer as quantity
    from jsonb_array_elements(p_items) entry
    group by (entry->>'productId')::uuid
  loop
    select * into v_product from public.products where id = v_item.product_id and active;
    insert into private.payment_intent_items(intent_id, product_id, quantity, unit_price_won, line_total_won)
    values (v_intent.id, v_product.id, v_item.quantity, v_product.selling_price_won, v_product.selling_price_won * v_item.quantity);
  end loop;

  return query select v_intent.id, v_intent.state, v_intent.total_won, v_intent.expires_at;
end;
$$;

create or replace function api.scan_payment_card(
  p_session_id uuid,
  p_intent_id uuid,
  p_card_fingerprint text
)
returns table(
  intent_id uuid,
  state private.intent_state,
  student_display_name text,
  current_balance_won bigint,
  projected_balance_won bigint,
  projected_debt_won bigint,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_intent private.payment_intents;
  v_student private.students;
  v_balance bigint;
  v_projected bigint;
begin
  v_session := private.assert_session(p_session_id, 'pos.checkout');
  select * into v_intent from private.payment_intents where id = p_intent_id for update;
  if not found or v_intent.staff_session_id <> v_session.id then raise exception 'NOT_FOUND'; end if;
  if v_intent.expires_at <= now() then
    update private.payment_intents set state = 'expired', updated_at = now() where id = v_intent.id;
    raise exception 'SESSION_EXPIRED';
  end if;
  if v_intent.state <> 'awaiting_card' then raise exception 'CONFLICT'; end if;

  select s.* into v_student
  from private.student_cards c
  join private.students s on s.id = c.student_id
  where c.card_fingerprint = p_card_fingerprint and c.active and s.active;
  if not found then raise exception 'NOT_FOUND'; end if;

  select balance_won into v_balance from private.wallets where student_id = v_student.id;
  if not found then raise exception 'NOT_FOUND'; end if;
  v_projected := v_balance - v_intent.total_won;

  update private.payment_intents
  set student_id = v_student.id, state = 'awaiting_pin', card_scanned_at = now(), updated_at = now()
  where id = v_intent.id;

  return query select
    v_intent.id, 'awaiting_pin'::private.intent_state, v_student.display_name,
    v_balance, v_projected, greatest(0::bigint, -v_projected), v_intent.expires_at;
end;
$$;

create or replace function api.confirm_payment(
  p_session_id uuid,
  p_intent_id uuid,
  p_student_pin_proof text
)
returns table(
  approved boolean,
  error_code text,
  sale_id uuid,
  receipt_number text,
  total_won bigint,
  balance_before_won bigint,
  balance_after_won bigint,
  debt_after_won bigint,
  cogs_won bigint,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_intent private.payment_intents;
  v_credential private.student_credentials;
  v_wallet private.wallets;
  v_settings private.system_settings;
  v_sale private.sales;
  v_item record;
  v_lot private.inventory_lots;
  v_sale_item_id uuid;
  v_needed integer;
  v_take integer;
  v_line_cogs bigint;
  v_all_cogs bigint := 0;
  v_cost bigint;
  v_projected bigint;
  v_ledger_id uuid;
  v_receipt text;
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'pos.checkout');
  select * into v_intent from private.payment_intents where id = p_intent_id for update;
  if not found or v_intent.staff_session_id <> v_session.id then raise exception 'NOT_FOUND'; end if;
  if v_intent.expires_at <= v_now then
    update private.payment_intents set state = 'expired', updated_at = v_now where id = v_intent.id;
    return query select false, 'SESSION_EXPIRED', null::uuid, null::text, v_intent.total_won,
      null::bigint, null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;
  if v_intent.state = 'completed' and v_intent.completed_sale_id is not null then
    return query
    select true, null::text, s.id, s.receipt_number, s.total_won,
      wl.balance_before_won, wl.balance_after_won, greatest(0::bigint, -wl.balance_after_won),
      s.cost_of_goods_sold_won, s.created_at
    from private.sales s join private.wallet_ledger wl on wl.id = s.wallet_ledger_id
    where s.id = v_intent.completed_sale_id;
    return;
  end if;
  if v_intent.state <> 'awaiting_pin' or v_intent.student_id is null then raise exception 'CONFLICT'; end if;

  select * into v_credential from private.student_credentials where student_id = v_intent.student_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if v_credential.locked_until is not null and v_credential.locked_until > v_now then
    return query select false, 'RATE_LIMITED', null::uuid, null::text, v_intent.total_won,
      null::bigint, null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;

  if extensions.crypt(p_student_pin_proof, v_credential.pin_hash) <> v_credential.pin_hash then
    update private.student_credentials
    set failed_attempts = failed_attempts + 1,
        locked_until = case when failed_attempts + 1 >= 3 then v_now + interval '5 minutes' else null end
    where student_id = v_intent.student_id;
    update private.payment_intents
    set pin_attempts = least(3, pin_attempts + 1),
        state = case when pin_attempts + 1 >= 3 then 'cancelled'::private.intent_state else state end,
        updated_at = v_now
    where id = v_intent.id;
    return query select false, 'INVALID_PIN', null::uuid, null::text, v_intent.total_won,
      null::bigint, null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;
  update private.student_credentials set failed_attempts = 0, locked_until = null where student_id = v_intent.student_id;

  select * into v_wallet from private.wallets where student_id = v_intent.student_id for update;
  select * into v_settings from private.system_settings where singleton;
  v_projected := v_wallet.balance_won - v_intent.total_won;
  if v_projected < v_settings.negative_wallet_limit_won then
    update private.payment_intents set state = 'cancelled', updated_at = v_now where id = v_intent.id;
    return query select false, 'WALLET_LIMIT', null::uuid, null::text, v_intent.total_won,
      v_wallet.balance_won, v_projected, greatest(0::bigint, -v_projected), null::bigint, v_now;
    return;
  end if;

  v_receipt := 'SALE-' || to_char(v_now, 'YYYYMMDD') || '-' || lpad(nextval('private.sale_receipt_sequence')::text, 6, '0');
  insert into private.sales(
    receipt_number, student_id, cashier_user_id, staff_session_id, total_won, payment_intent_id
  ) values (
    v_receipt, v_intent.student_id, v_session.auth_user_id, v_session.id, v_intent.total_won, v_intent.id
  ) returning * into v_sale;

  for v_item in
    select pii.*, p.name as product_name
    from private.payment_intent_items pii
    join public.products p on p.id = pii.product_id
    where pii.intent_id = v_intent.id
    order by pii.id
  loop
    if (select coalesce(sum(quantity_remaining),0) from private.inventory_lots where product_id = v_item.product_id and quantity_remaining > 0) < v_item.quantity then
      raise exception 'INVENTORY_SHORTAGE';
    end if;

    insert into private.sale_items(
      sale_id, product_id, product_name_snapshot, quantity, unit_price_won, line_total_won
    ) values (
      v_sale.id, v_item.product_id, v_item.product_name, v_item.quantity, v_item.unit_price_won, v_item.line_total_won
    ) returning id into v_sale_item_id;

    v_needed := v_item.quantity;
    v_line_cogs := 0;
    for v_lot in
      select l.* from private.inventory_lots l
      where l.product_id = v_item.product_id and l.quantity_remaining > 0
      order by
        case when v_settings.inventory_cost_method = 'FIFO' then l.received_at end asc,
        case when v_settings.inventory_cost_method = 'FIFO' then l.id end asc,
        case when v_settings.inventory_cost_method = 'LIFO' then l.received_at end desc,
        case when v_settings.inventory_cost_method = 'LIFO' then l.id end desc
      for update
    loop
      exit when v_needed = 0;
      v_take := least(v_needed, v_lot.quantity_remaining);
      v_cost := round(v_take * v_lot.landed_unit_cost_won)::bigint;

      update private.inventory_lots set quantity_remaining = quantity_remaining - v_take where id = v_lot.id;
      insert into private.sale_cost_allocations(sale_item_id, inventory_lot_id, quantity, unit_cost_won, total_cost_won)
      values (v_sale_item_id, v_lot.id, v_take, v_lot.landed_unit_cost_won, v_cost);
      insert into private.inventory_movements(
        product_id, lot_id, movement_type, quantity_change, unit_cost_won, total_cost_won,
        reason_code, staff_user_id, staff_session_id, source_type, source_id, idempotency_key
      ) values (
        v_item.product_id, v_lot.id, 'SALE', -v_take, v_lot.landed_unit_cost_won, -v_cost,
        'STUDENT_SALE', v_session.auth_user_id, v_session.id, 'SALE_ITEM', v_sale_item_id, v_intent.idempotency_key
      );
      v_line_cogs := v_line_cogs + v_cost;
      v_needed := v_needed - v_take;
    end loop;
    if v_needed <> 0 then raise exception 'INVENTORY_SHORTAGE'; end if;
    update private.sale_items set cogs_won = v_line_cogs where id = v_sale_item_id;
    v_all_cogs := v_all_cogs + v_line_cogs;
  end loop;

  insert into private.wallet_ledger(
    reference_number, student_id, amount_won, entry_type, reason_code,
    balance_before_won, balance_after_won, staff_user_id, staff_session_id,
    source_type, source_id, idempotency_key
  ) values (
    'PAY-' || v_receipt, v_intent.student_id, -v_intent.total_won, 'PURCHASE', 'POS_SALE',
    v_wallet.balance_won, v_projected, v_session.auth_user_id, v_session.id,
    'SALE', v_sale.id, v_intent.idempotency_key
  ) returning id into v_ledger_id;

  update private.wallets set balance_won = v_projected, updated_at = v_now where student_id = v_intent.student_id;
  update private.sales set cost_of_goods_sold_won = v_all_cogs, wallet_ledger_id = v_ledger_id where id = v_sale.id;
  update private.payment_intents set state = 'completed', completed_sale_id = v_sale.id, updated_at = v_now where id = v_intent.id;

  insert into private.audit_events(event_type, actor_user_id, staff_session_id, subject_type, subject_id, reference_number, safe_payload)
  values ('SALE_COMPLETED', v_session.auth_user_id, v_session.id, 'SALE', v_sale.id,
          'AUD-' || v_receipt, jsonb_build_object('total_won', v_intent.total_won, 'cogs_won', v_all_cogs));

  return query select true, null::text, v_sale.id, v_receipt, v_intent.total_won,
    v_wallet.balance_won, v_projected, greatest(0::bigint, -v_projected), v_all_cogs, v_now;
end;
$$;
-- END 003_pos_functions.sql

-- BEGIN 004_inventory_functions.sql
create table if not exists private.stock_adjustments (
  id uuid primary key default gen_random_uuid(),
  reference_number text not null unique,
  product_id uuid not null references public.products(id) on delete restrict,
  requested_lot_id uuid references private.inventory_lots(id) on delete restrict,
  quantity_removed integer not null check (quantity_removed > 0),
  reason_code text not null check (reason_code in ('DAMAGED','EXPIRED','SUPPLIER_RETURN','STOCK_COUNT_LOSS')),
  notes text not null,
  total_cost_won bigint not null check (total_cost_won >= 0),
  adjusted_by uuid not null references auth.users(id) on delete restrict,
  staff_session_id uuid not null references private.staff_sessions(id) on delete restrict,
  idempotency_key uuid not null unique,
  created_at timestamptz not null default now()
);
revoke all on private.stock_adjustments from public, anon, authenticated;

create or replace function api.create_product(
  p_session_id uuid,
  p_sku text,
  p_name text,
  p_category text,
  p_selling_price_won bigint,
  p_reorder_level integer
)
returns table(reference_id uuid, reference_number text, created_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_product public.products;
begin
  v_session := private.assert_session(p_session_id, 'inventory.product.manage');
  if length(trim(p_sku)) < 1 or length(trim(p_name)) < 1 or length(trim(p_category)) < 1
     or p_selling_price_won < 0 or p_reorder_level < 0 then raise exception 'BAD_REQUEST'; end if;

  insert into public.products(sku, name, category, selling_price_won, reorder_level, created_by)
  values (trim(p_sku), trim(p_name), trim(p_category), p_selling_price_won, p_reorder_level, v_session.auth_user_id)
  returning * into v_product;

  insert into private.audit_events(event_type, actor_user_id, staff_session_id, subject_type, subject_id, reference_number, safe_payload)
  values ('PRODUCT_CREATED', v_session.auth_user_id, v_session.id, 'PRODUCT', v_product.id,
    'AUD-PRODUCT-' || substr(v_product.id::text, 1, 8),
    jsonb_build_object('sku', v_product.sku, 'selling_price_won', v_product.selling_price_won));

  return query select v_product.id, 'PRODUCT-' || v_product.sku, v_product.created_at;
end;
$$;

create or replace function api.change_product_price(
  p_session_id uuid,
  p_product_id uuid,
  p_new_price_won bigint,
  p_reason text
)
returns table(reference_id uuid, reference_number text, created_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_product public.products;
  v_history private.product_price_history;
begin
  v_session := private.assert_session(p_session_id, 'inventory.price.manage');
  if p_new_price_won < 0 or length(trim(p_reason)) < 3 then raise exception 'BAD_REQUEST'; end if;
  select * into v_product from public.products where id = p_product_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if v_product.selling_price_won = p_new_price_won then raise exception 'CONFLICT'; end if;

  insert into private.product_price_history(
    product_id, old_price_won, new_price_won, reason, changed_by, staff_session_id
  ) values (
    v_product.id, v_product.selling_price_won, p_new_price_won, trim(p_reason), v_session.auth_user_id, v_session.id
  ) returning * into v_history;

  update public.products set selling_price_won = p_new_price_won, updated_at = now() where id = v_product.id;
  return query select v_history.id, 'PRICE-' || substr(v_history.id::text, 1, 8), v_history.changed_at;
end;
$$;

create or replace function api.inventory_lots(p_session_id uuid)
returns table(
  lot_id uuid,
  product_id uuid,
  product_name text,
  receipt_number text,
  received_at timestamptz,
  expiration_date date,
  quantity_received integer,
  quantity_remaining integer,
  landed_unit_cost_won bigint,
  inventory_value_won bigint
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session_any(p_session_id, array['inventory.read','reports.inventory']);
  return query
  select l.id, l.product_id, p.name, r.receipt_number, l.received_at, l.expiration_date,
    l.quantity_received, l.quantity_remaining,
    round(l.landed_unit_cost_won)::bigint,
    round(l.quantity_remaining * l.landed_unit_cost_won)::bigint
  from private.inventory_lots l
  join public.products p on p.id = l.product_id
  join private.stock_receipt_lines rl on rl.id = l.receipt_line_id
  join private.stock_receipts r on r.id = rl.receipt_id
  order by p.name, l.received_at, l.id;
end;
$$;

create or replace function api.receive_stock(
  p_session_id uuid,
  p_supplier_name text,
  p_supplier_invoice text,
  p_purchase_date date,
  p_shipping_won bigint,
  p_other_costs_won bigint,
  p_discount_won bigint,
  p_notes text,
  p_lines jsonb,
  p_idempotency_key uuid
)
returns table(
  receipt_id uuid,
  receipt_number text,
  total_quantity bigint,
  purchase_subtotal_won bigint,
  total_landed_cost_won bigint,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_existing private.stock_receipts;
  v_receipt private.stock_receipts;
  v_line record;
  v_product public.products;
  v_line_count integer;
  v_index integer := 0;
  v_total_quantity bigint := 0;
  v_subtotal bigint := 0;
  v_base bigint;
  v_weight bigint;
  v_weight_total bigint := 0;
  v_overhead_total bigint;
  v_overhead_alloc bigint;
  v_discount_alloc bigint;
  v_overhead_assigned bigint := 0;
  v_discount_assigned bigint := 0;
  v_line_landed bigint;
  v_line_id uuid;
  v_lot_id uuid;
  v_receipt_number text;
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'inventory.receive');
  if p_shipping_won < 0 or p_other_costs_won < 0 or p_discount_won < 0
     or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) < 1 or jsonb_array_length(p_lines) > 200
     or length(trim(p_supplier_name)) < 1 or length(trim(p_supplier_invoice)) < 1 then
    raise exception 'BAD_REQUEST';
  end if;

  select * into v_existing from private.stock_receipts where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.staff_session_id <> v_session.id then raise exception 'CONFLICT'; end if;
    return query select v_existing.id, v_existing.receipt_number,
      (select sum(quantity)::bigint from private.stock_receipt_lines where receipt_id = v_existing.id),
      v_existing.purchase_subtotal_won, v_existing.total_landed_cost_won, v_existing.created_at;
    return;
  end if;

  v_line_count := jsonb_array_length(p_lines);
  for v_line in
    select entry, ordinality::integer as ordinal
    from jsonb_array_elements(p_lines) with ordinality as x(entry, ordinality)
  loop
    if (v_line.entry->>'quantity')::integer < 1 or (v_line.entry->>'purchaseUnitCostWon')::bigint < 0 then
      raise exception 'BAD_REQUEST';
    end if;
    select * into v_product from public.products where id = (v_line.entry->>'productId')::uuid and active;
    if not found then raise exception 'NOT_FOUND'; end if;
    v_base := (v_line.entry->>'quantity')::bigint * (v_line.entry->>'purchaseUnitCostWon')::bigint;
    v_subtotal := v_subtotal + v_base;
    v_total_quantity := v_total_quantity + (v_line.entry->>'quantity')::integer;
  end loop;
  v_weight_total := case when v_subtotal > 0 then v_subtotal else v_total_quantity end;
  v_overhead_total := p_shipping_won + p_other_costs_won;
  if p_discount_won > v_subtotal + v_overhead_total then raise exception 'BAD_REQUEST'; end if;

  v_receipt_number := 'RCV-' || to_char(v_now, 'YYYYMMDD') || '-' || lpad(nextval('private.stock_receipt_sequence')::text, 6, '0');
  insert into private.stock_receipts(
    receipt_number, supplier_name, supplier_invoice, purchase_date,
    purchase_subtotal_won, shipping_won, other_costs_won, discount_won, total_landed_cost_won,
    notes, received_by, staff_session_id, idempotency_key
  ) values (
    v_receipt_number, trim(p_supplier_name), trim(p_supplier_invoice), p_purchase_date,
    v_subtotal, p_shipping_won, p_other_costs_won, p_discount_won,
    v_subtotal + v_overhead_total - p_discount_won,
    nullif(trim(coalesce(p_notes,'')),''), v_session.auth_user_id, v_session.id, p_idempotency_key
  ) returning * into v_receipt;

  for v_line in
    select entry, ordinality::integer as ordinal
    from jsonb_array_elements(p_lines) with ordinality as x(entry, ordinality)
    order by ordinality
  loop
    v_index := v_index + 1;
    v_base := (v_line.entry->>'quantity')::bigint * (v_line.entry->>'purchaseUnitCostWon')::bigint;
    v_weight := case when v_subtotal > 0 then v_base else (v_line.entry->>'quantity')::bigint end;
    if v_index = v_line_count then
      v_overhead_alloc := v_overhead_total - v_overhead_assigned;
      v_discount_alloc := p_discount_won - v_discount_assigned;
    else
      v_overhead_alloc := floor(v_overhead_total::numeric * v_weight / v_weight_total)::bigint;
      v_discount_alloc := floor(p_discount_won::numeric * v_weight / v_weight_total)::bigint;
      v_overhead_assigned := v_overhead_assigned + v_overhead_alloc;
      v_discount_assigned := v_discount_assigned + v_discount_alloc;
    end if;
    v_line_landed := v_base + v_overhead_alloc - v_discount_alloc;
    if v_line_landed < 0 then raise exception 'BAD_REQUEST'; end if;

    insert into private.stock_receipt_lines(
      receipt_id, product_id, quantity, purchase_unit_cost_won, base_cost_won,
      allocated_overhead_won, allocated_discount_won, total_landed_cost_won,
      supplier_lot_code, expiration_date
    ) values (
      v_receipt.id, (v_line.entry->>'productId')::uuid, (v_line.entry->>'quantity')::integer,
      (v_line.entry->>'purchaseUnitCostWon')::bigint, v_base,
      v_overhead_alloc, v_discount_alloc, v_line_landed,
      nullif(trim(coalesce(v_line.entry->>'supplierLotCode','')),''),
      nullif(v_line.entry->>'expirationDate','')::date
    ) returning id into v_line_id;

    insert into private.inventory_lots(
      receipt_line_id, product_id, received_at, expiration_date,
      quantity_received, quantity_remaining, landed_unit_cost_won
    ) values (
      v_line_id, (v_line.entry->>'productId')::uuid, v_now,
      nullif(v_line.entry->>'expirationDate','')::date,
      (v_line.entry->>'quantity')::integer, (v_line.entry->>'quantity')::integer,
      v_line_landed::numeric / (v_line.entry->>'quantity')::integer
    ) returning id into v_lot_id;

    insert into private.inventory_movements(
      product_id, lot_id, movement_type, quantity_change, unit_cost_won, total_cost_won,
      reason_code, notes, staff_user_id, staff_session_id, source_type, source_id, idempotency_key
    ) values (
      (v_line.entry->>'productId')::uuid, v_lot_id, 'PURCHASE_RECEIPT',
      (v_line.entry->>'quantity')::integer,
      v_line_landed::numeric / (v_line.entry->>'quantity')::integer, v_line_landed,
      'PURCHASE_RECEIPT', p_notes, v_session.auth_user_id, v_session.id, 'STOCK_RECEIPT', v_receipt.id, p_idempotency_key
    );
  end loop;

  insert into private.audit_events(event_type, actor_user_id, staff_session_id, subject_type, subject_id, reference_number, safe_payload)
  values ('STOCK_RECEIPT_POSTED', v_session.auth_user_id, v_session.id, 'STOCK_RECEIPT', v_receipt.id,
    'AUD-' || v_receipt.receipt_number,
    jsonb_build_object('total_quantity', v_total_quantity, 'total_landed_cost_won', v_receipt.total_landed_cost_won));

  return query select v_receipt.id, v_receipt.receipt_number, v_total_quantity,
    v_receipt.purchase_subtotal_won, v_receipt.total_landed_cost_won, v_receipt.created_at;
end;
$$;

create or replace function api.remove_stock(
  p_session_id uuid,
  p_product_id uuid,
  p_lot_id uuid,
  p_quantity integer,
  p_reason_code text,
  p_notes text,
  p_idempotency_key uuid
)
returns table(reference_id uuid, reference_number text, created_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_existing private.stock_adjustments;
  v_adjustment private.stock_adjustments;
  v_settings private.system_settings;
  v_lot private.inventory_lots;
  v_needed integer;
  v_take integer;
  v_cost bigint;
  v_total_cost bigint := 0;
  v_reference text;
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'inventory.adjust');
  if p_quantity < 1 or p_reason_code not in ('DAMAGED','EXPIRED','SUPPLIER_RETURN','STOCK_COUNT_LOSS')
     or length(trim(p_notes)) < 3 then raise exception 'BAD_REQUEST'; end if;
  if not exists(select 1 from public.products where id = p_product_id) then raise exception 'NOT_FOUND'; end if;

  select * into v_existing from private.stock_adjustments where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.staff_session_id <> v_session.id then raise exception 'CONFLICT'; end if;
    return query select v_existing.id, v_existing.reference_number, v_existing.created_at;
    return;
  end if;

  if (select coalesce(sum(quantity_remaining),0) from private.inventory_lots
      where product_id = p_product_id and quantity_remaining > 0 and (p_lot_id is null or id = p_lot_id)) < p_quantity then
    raise exception 'INVENTORY_SHORTAGE';
  end if;

  select * into v_settings from private.system_settings where singleton;
  v_reference := 'ADJ-' || to_char(v_now, 'YYYYMMDD') || '-' || lpad(nextval('private.adjustment_sequence')::text, 6, '0');
  insert into private.stock_adjustments(
    reference_number, product_id, requested_lot_id, quantity_removed, reason_code, notes,
    total_cost_won, adjusted_by, staff_session_id, idempotency_key
  ) values (
    v_reference, p_product_id, p_lot_id, p_quantity, p_reason_code, trim(p_notes),
    0, v_session.auth_user_id, v_session.id, p_idempotency_key
  ) returning * into v_adjustment;

  v_needed := p_quantity;
  for v_lot in
    select l.* from private.inventory_lots l
    where l.product_id = p_product_id and l.quantity_remaining > 0 and (p_lot_id is null or l.id = p_lot_id)
    order by
      case when p_lot_id is not null then 0 else 1 end,
      case when v_settings.inventory_cost_method = 'FIFO' then l.received_at end asc,
      case when v_settings.inventory_cost_method = 'FIFO' then l.id end asc,
      case when v_settings.inventory_cost_method = 'LIFO' then l.received_at end desc,
      case when v_settings.inventory_cost_method = 'LIFO' then l.id end desc
    for update
  loop
    exit when v_needed = 0;
    v_take := least(v_needed, v_lot.quantity_remaining);
    v_cost := round(v_take * v_lot.landed_unit_cost_won)::bigint;
    update private.inventory_lots set quantity_remaining = quantity_remaining - v_take where id = v_lot.id;
    insert into private.inventory_movements(
      product_id, lot_id, movement_type, quantity_change, unit_cost_won, total_cost_won,
      reason_code, notes, staff_user_id, staff_session_id, source_type, source_id, idempotency_key
    ) values (
      p_product_id, v_lot.id, p_reason_code::private.inventory_movement_type, -v_take,
      v_lot.landed_unit_cost_won, -v_cost, p_reason_code, trim(p_notes),
      v_session.auth_user_id, v_session.id, 'STOCK_ADJUSTMENT', v_adjustment.id, p_idempotency_key
    );
    v_total_cost := v_total_cost + v_cost;
    v_needed := v_needed - v_take;
  end loop;
  if v_needed <> 0 then raise exception 'INVENTORY_SHORTAGE'; end if;
  update private.stock_adjustments set total_cost_won = v_total_cost where id = v_adjustment.id;

  insert into private.audit_events(event_type, actor_user_id, staff_session_id, subject_type, subject_id, reference_number, safe_payload)
  values ('STOCK_REMOVED', v_session.auth_user_id, v_session.id, 'STOCK_ADJUSTMENT', v_adjustment.id,
    'AUD-' || v_reference, jsonb_build_object('quantity', p_quantity, 'reason_code', p_reason_code, 'cost_won', v_total_cost));

  return query select v_adjustment.id, v_reference, v_now;
end;
$$;
-- END 004_inventory_functions.sql

-- BEGIN 005_wallet_functions.sql
create or replace function api.search_student_wallets(p_session_id uuid, p_query text default '')
returns table(
  student_id uuid,
  student_code text,
  display_name text,
  balance_won bigint,
  debt_won bigint,
  card_active boolean
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session(p_session_id, 'wallet.read');
  return query
  select s.id, s.student_code, s.display_name, w.balance_won,
    greatest(0::bigint, -w.balance_won),
    exists(select 1 from private.student_cards c where c.student_id = s.id and c.active)
  from private.students s
  join private.wallets w on w.student_id = s.id
  where s.active and (
    trim(coalesce(p_query,'')) = ''
    or s.student_code ilike '%' || trim(p_query) || '%'
    or s.display_name ilike '%' || trim(p_query) || '%'
  )
  order by case when w.balance_won < 0 then 0 else 1 end, s.display_name
  limit 100;
end;
$$;

create or replace function api.create_wallet_adjustment_intent(
  p_session_id uuid,
  p_direction text,
  p_denominations integer[],
  p_reason_code text,
  p_notes text,
  p_idempotency_key uuid
)
returns table(
  intent_id uuid,
  direction private.wallet_direction,
  amount_won bigint,
  state private.intent_state,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_existing private.wallet_adjustment_intents;
  v_intent private.wallet_adjustment_intents;
  v_denom integer;
  v_amount bigint := 0;
begin
  v_session := private.assert_session(p_session_id, 'wallet.adjust');
  if p_direction not in ('CREDIT','DEBIT')
     or coalesce(array_length(p_denominations,1),0) < 1
     or array_length(p_denominations,1) > 30
     or length(trim(p_notes)) < 3 then raise exception 'BAD_REQUEST'; end if;

  foreach v_denom in array p_denominations loop
    if v_denom <> all(array[1000,5000,10000,20000,50000]) then raise exception 'BAD_REQUEST'; end if;
    v_amount := v_amount + v_denom;
  end loop;
  if v_amount <= 0 then raise exception 'BAD_REQUEST'; end if;

  if p_direction = 'CREDIT' and p_reason_code <> 'FUNDS_RECEIVED' then raise exception 'BAD_REQUEST'; end if;
  if p_direction = 'DEBIT' and p_reason_code not in (
    'PURCHASE_CORRECTION','DUPLICATE_CREDIT_REVERSAL','ADMINISTRATIVE_CHARGE','OTHER_APPROVED_CORRECTION'
  ) then raise exception 'BAD_REQUEST'; end if;

  select * into v_existing from private.wallet_adjustment_intents where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.staff_session_id <> v_session.id then raise exception 'CONFLICT'; end if;
    return query select v_existing.id, v_existing.direction, v_existing.amount_won, v_existing.state, v_existing.expires_at;
    return;
  end if;

  insert into private.wallet_adjustment_intents(
    idempotency_key, staff_session_id, direction, amount_won, denominations,
    reason_code, notes, state, expires_at
  ) values (
    p_idempotency_key, v_session.id, p_direction::private.wallet_direction, v_amount, p_denominations,
    p_reason_code, trim(p_notes), 'awaiting_card', now() + interval '60 seconds'
  ) returning * into v_intent;

  return query select v_intent.id, v_intent.direction, v_intent.amount_won, v_intent.state, v_intent.expires_at;
end;
$$;

create or replace function api.scan_wallet_adjustment_card(
  p_session_id uuid,
  p_intent_id uuid,
  p_card_fingerprint text
)
returns table(
  intent_id uuid,
  state private.intent_state,
  student_id uuid,
  student_display_name text,
  balance_before_won bigint,
  projected_balance_won bigint,
  projected_debt_won bigint
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_intent private.wallet_adjustment_intents;
  v_student private.students;
  v_balance bigint;
  v_projected bigint;
begin
  v_session := private.assert_session(p_session_id, 'wallet.adjust');
  select * into v_intent from private.wallet_adjustment_intents where id = p_intent_id for update;
  if not found or v_intent.staff_session_id <> v_session.id then raise exception 'NOT_FOUND'; end if;
  if v_intent.expires_at <= now() then
    update private.wallet_adjustment_intents set state = 'expired', updated_at = now() where id = v_intent.id;
    raise exception 'SESSION_EXPIRED';
  end if;
  if v_intent.state <> 'awaiting_card' then raise exception 'CONFLICT'; end if;

  select s.* into v_student
  from private.student_cards c
  join private.students s on s.id = c.student_id
  where c.card_fingerprint = p_card_fingerprint and c.active and s.active;
  if not found then raise exception 'NOT_FOUND'; end if;
  select balance_won into v_balance from private.wallets where student_id = v_student.id;
  if not found then raise exception 'NOT_FOUND'; end if;

  v_projected := case when v_intent.direction = 'CREDIT'
    then v_balance + v_intent.amount_won else v_balance - v_intent.amount_won end;
  update private.wallet_adjustment_intents
  set student_id = v_student.id, state = 'awaiting_pin', updated_at = now()
  where id = v_intent.id;

  return query select v_intent.id, 'awaiting_pin'::private.intent_state,
    v_student.id, v_student.display_name, v_balance, v_projected, greatest(0::bigint, -v_projected);
end;
$$;

create or replace function api.confirm_wallet_adjustment(
  p_session_id uuid,
  p_intent_id uuid,
  p_student_pin_proof text
)
returns table(
  approved boolean,
  error_code text,
  ledger_id uuid,
  reference_number text,
  amount_won bigint,
  balance_before_won bigint,
  balance_after_won bigint,
  debt_after_won bigint,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_intent private.wallet_adjustment_intents;
  v_credential private.student_credentials;
  v_wallet private.wallets;
  v_settings private.system_settings;
  v_projected bigint;
  v_signed_amount bigint;
  v_ledger private.wallet_ledger;
  v_reference text;
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'wallet.adjust');
  select * into v_intent from private.wallet_adjustment_intents where id = p_intent_id for update;
  if not found or v_intent.staff_session_id <> v_session.id then raise exception 'NOT_FOUND'; end if;
  if v_intent.expires_at <= v_now then
    update private.wallet_adjustment_intents set state = 'expired', updated_at = v_now where id = v_intent.id;
    return query select false, 'SESSION_EXPIRED', null::uuid, null::text, null::bigint,
      null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;
  if v_intent.state = 'completed' and v_intent.completed_ledger_id is not null then
    return query select true, null::text, wl.id, wl.reference_number, wl.amount_won,
      wl.balance_before_won, wl.balance_after_won, greatest(0::bigint, -wl.balance_after_won), wl.created_at
    from private.wallet_ledger wl where wl.id = v_intent.completed_ledger_id;
    return;
  end if;
  if v_intent.state <> 'awaiting_pin' or v_intent.student_id is null then raise exception 'CONFLICT'; end if;

  select * into v_credential from private.student_credentials where student_id = v_intent.student_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if v_credential.locked_until is not null and v_credential.locked_until > v_now then
    return query select false, 'RATE_LIMITED', null::uuid, null::text, null::bigint,
      null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;
  if extensions.crypt(p_student_pin_proof, v_credential.pin_hash) <> v_credential.pin_hash then
    update private.student_credentials
    set failed_attempts = failed_attempts + 1,
        locked_until = case when failed_attempts + 1 >= 3 then v_now + interval '5 minutes' else null end
    where student_id = v_intent.student_id;
    update private.wallet_adjustment_intents
    set pin_attempts = least(3, pin_attempts + 1),
        state = case when pin_attempts + 1 >= 3 then 'cancelled'::private.intent_state else state end,
        updated_at = v_now
    where id = v_intent.id;
    return query select false, 'INVALID_PIN', null::uuid, null::text, null::bigint,
      null::bigint, null::bigint, null::bigint, v_now;
    return;
  end if;
  update private.student_credentials set failed_attempts = 0, locked_until = null where student_id = v_intent.student_id;

  select * into v_wallet from private.wallets where student_id = v_intent.student_id for update;
  select * into v_settings from private.system_settings where singleton;
  v_signed_amount := case when v_intent.direction = 'CREDIT' then v_intent.amount_won else -v_intent.amount_won end;
  v_projected := v_wallet.balance_won + v_signed_amount;
  if v_projected < v_settings.negative_wallet_limit_won then
    update private.wallet_adjustment_intents set state = 'cancelled', updated_at = v_now where id = v_intent.id;
    return query select false, 'WALLET_LIMIT', null::uuid, null::text, v_signed_amount,
      v_wallet.balance_won, v_projected, greatest(0::bigint, -v_projected), v_now;
    return;
  end if;

  v_reference := 'WAL-' || to_char(v_now, 'YYYYMMDD') || '-' || lpad(nextval('private.adjustment_sequence')::text, 6, '0');
  insert into private.wallet_ledger(
    reference_number, student_id, amount_won, entry_type, reason_code,
    balance_before_won, balance_after_won, staff_user_id, staff_session_id,
    source_type, source_id, idempotency_key, notes
  ) values (
    v_reference, v_intent.student_id, v_signed_amount,
    case when v_signed_amount > 0 then 'FUNDS_ADDED' else 'CONTROLLED_DEDUCTION' end,
    v_intent.reason_code, v_wallet.balance_won, v_projected,
    v_session.auth_user_id, v_session.id, 'WALLET_ADJUSTMENT', v_intent.id, v_intent.idempotency_key, v_intent.notes
  ) returning * into v_ledger;

  update private.wallets set balance_won = v_projected, updated_at = v_now where student_id = v_intent.student_id;
  update private.wallet_adjustment_intents set state = 'completed', completed_ledger_id = v_ledger.id, updated_at = v_now where id = v_intent.id;

  insert into private.audit_events(event_type, actor_user_id, staff_session_id, subject_type, subject_id, reference_number, safe_payload)
  values ('WALLET_ADJUSTMENT_POSTED', v_session.auth_user_id, v_session.id, 'WALLET_LEDGER', v_ledger.id,
    'AUD-' || v_reference, jsonb_build_object('amount_won', v_signed_amount, 'reason_code', v_intent.reason_code));

  return query select true, null::text, v_ledger.id, v_reference, v_signed_amount,
    v_wallet.balance_won, v_projected, greatest(0::bigint, -v_projected), v_now;
end;
$$;
-- END 005_wallet_functions.sql

-- BEGIN 006_security_functions.sql
create or replace function api.create_elevation(
  p_session_id uuid,
  p_approver_user_id uuid,
  p_purpose text,
  p_student_id uuid,
  p_token_hash text
)
returns table(expires_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_approver public.staff_profiles;
  v_expiry timestamptz := now() + interval '60 seconds';
begin
  v_session := private.assert_session(p_session_id, 'security.credentials.request');
  if p_purpose not in ('RESET_STUDENT_PIN','RESET_STUDENT_CARD') or length(p_token_hash) <> 64 then raise exception 'BAD_REQUEST'; end if;
  if not exists(select 1 from private.students where id = p_student_id and active) then raise exception 'NOT_FOUND'; end if;

  select * into v_approver from public.staff_profiles
  where auth_user_id = p_approver_user_id and active and role = 'super_admin';
  if not found then raise exception 'FORBIDDEN'; end if;

  insert into private.elevation_tokens(
    token_hash, requested_by, approved_by, staff_session_id, purpose, student_id, expires_at
  ) values (
    p_token_hash, v_session.auth_user_id, p_approver_user_id, v_session.id, p_purpose, p_student_id, v_expiry
  );

  insert into private.audit_events(event_type, actor_user_id, approver_user_id, staff_session_id,
    subject_type, subject_id, reference_number, safe_payload)
  values ('CREDENTIAL_RESET_AUTHORIZED', v_session.auth_user_id, p_approver_user_id, v_session.id,
    'STUDENT', p_student_id, 'AUD-ELEV-' || substr(gen_random_uuid()::text,1,8), jsonb_build_object('purpose', p_purpose));

  return query select v_expiry;
end;
$$;

create or replace function private.consume_elevation(
  p_session private.staff_sessions,
  p_token_hash text,
  p_purpose text,
  p_student_id uuid
)
returns private.elevation_tokens
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_token private.elevation_tokens;
begin
  select * into v_token from private.elevation_tokens
  where token_hash = p_token_hash
    and staff_session_id = p_session.id
    and requested_by = p_session.auth_user_id
    and purpose = p_purpose
    and student_id = p_student_id
    and consumed_at is null
    and expires_at > now()
  for update;
  if not found then raise exception 'FORBIDDEN'; end if;
  update private.elevation_tokens set consumed_at = now() where id = v_token.id returning * into v_token;
  return v_token;
end;
$$;

create or replace function api.reset_student_pin(
  p_session_id uuid,
  p_student_id uuid,
  p_elevation_token_hash text,
  p_new_pin_proof text
)
returns table(audit_reference text, completed_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_elevation private.elevation_tokens;
  v_reference text := 'AUD-PIN-' || substr(gen_random_uuid()::text,1,8);
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'security.credentials.request');
  if p_new_pin_proof !~ '^[a-f0-9]{64}$' then raise exception 'BAD_REQUEST'; end if;
  v_elevation := private.consume_elevation(v_session, p_elevation_token_hash, 'RESET_STUDENT_PIN', p_student_id);

  update private.student_credentials
  set pin_hash = extensions.crypt(p_new_pin_proof, extensions.gen_salt('bf', 12)),
      failed_attempts = 0, locked_until = null, pin_updated_at = v_now
  where student_id = p_student_id;
  if not found then raise exception 'NOT_FOUND'; end if;

  insert into private.audit_events(event_type, actor_user_id, approver_user_id, staff_session_id,
    subject_type, subject_id, reference_number, safe_payload)
  values ('STUDENT_PIN_RESET', v_session.auth_user_id, v_elevation.approved_by, v_session.id,
    'STUDENT', p_student_id, v_reference, '{}'::jsonb);
  return query select v_reference, v_now;
end;
$$;

create or replace function api.reset_student_card(
  p_session_id uuid,
  p_student_id uuid,
  p_elevation_token_hash text,
  p_new_card_fingerprint text
)
returns table(audit_reference text, completed_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.staff_sessions;
  v_elevation private.elevation_tokens;
  v_reference text := 'AUD-CARD-' || substr(gen_random_uuid()::text,1,8);
  v_now timestamptz := now();
begin
  v_session := private.assert_session(p_session_id, 'security.credentials.request');
  if length(p_new_card_fingerprint) <> 64 then raise exception 'BAD_REQUEST'; end if;
  v_elevation := private.consume_elevation(v_session, p_elevation_token_hash, 'RESET_STUDENT_CARD', p_student_id);

  update private.student_cards set active = false, deactivated_at = v_now
  where student_id = p_student_id and active;
  insert into private.student_cards(student_id, card_fingerprint, active, issued_by)
  values (p_student_id, p_new_card_fingerprint, true, v_session.auth_user_id);

  insert into private.audit_events(event_type, actor_user_id, approver_user_id, staff_session_id,
    subject_type, subject_id, reference_number, safe_payload)
  values ('STUDENT_CARD_RESET', v_session.auth_user_id, v_elevation.approved_by, v_session.id,
    'STUDENT', p_student_id, v_reference, '{}'::jsonb);
  return query select v_reference, v_now;
end;
$$;
-- END 006_security_functions.sql

-- BEGIN 007_reports_and_grants.sql
create or replace function api.report_sales(
  p_session_id uuid,
  p_from date default null,
  p_to date default null
)
returns table(
  receipt_number text,
  created_at timestamptz,
  cashier_name text,
  revenue_won bigint,
  cogs_won bigint,
  gross_profit_won bigint,
  student_code text,
  balance_after_won bigint
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session(p_session_id, 'reports.sales');
  return query
  select s.receipt_number, s.created_at, sp.display_name,
    s.total_won, s.cost_of_goods_sold_won, s.total_won - s.cost_of_goods_sold_won,
    st.student_code, wl.balance_after_won
  from private.sales s
  join public.staff_profiles sp on sp.auth_user_id = s.cashier_user_id
  join private.students st on st.id = s.student_id
  join private.wallet_ledger wl on wl.id = s.wallet_ledger_id
  where (p_from is null or s.created_at >= p_from::timestamptz)
    and (p_to is null or s.created_at < (p_to + 1)::timestamptz)
  order by s.created_at desc
  limit 5000;
end;
$$;

create or replace function api.report_inventory(p_session_id uuid)
returns table(
  product_name text,
  sku text,
  quantity_on_hand bigint,
  inventory_value_won bigint,
  oldest_receipt_date date,
  next_expiration_date date
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session(p_session_id, 'reports.inventory');
  return query
  select p.name, p.sku,
    coalesce(sum(l.quantity_remaining),0)::bigint,
    coalesce(round(sum(l.quantity_remaining * l.landed_unit_cost_won)),0)::bigint,
    min(r.purchase_date) filter (where l.quantity_remaining > 0),
    min(l.expiration_date) filter (where l.quantity_remaining > 0 and l.expiration_date is not null)
  from public.products p
  left join private.inventory_lots l on l.product_id = p.id
  left join private.stock_receipt_lines rl on rl.id = l.receipt_line_id
  left join private.stock_receipts r on r.id = rl.receipt_id
  where p.active
  group by p.id, p.name, p.sku
  order by p.name;
end;
$$;

create or replace function api.report_wallets(p_session_id uuid)
returns table(
  student_code text,
  display_name text,
  balance_won bigint,
  debt_won bigint,
  last_movement_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_session(p_session_id, 'reports.wallets');
  return query
  select s.student_code, s.display_name, w.balance_won,
    greatest(0::bigint, -w.balance_won), max(wl.created_at)
  from private.students s
  join private.wallets w on w.student_id = s.id
  left join private.wallet_ledger wl on wl.student_id = s.id
  where s.active
  group by s.id, s.student_code, s.display_name, w.balance_won
  order by case when w.balance_won < 0 then 0 else 1 end, s.display_name;
end;
$$;

